function initVisualEffects(){
  const main=$('main');
  if(!main||$('.background-motion-layer'))return;
  const layer=document.createElement('div');
  layer.className='background-motion-layer';
  layer.setAttribute('aria-hidden','true');
  layer.innerHTML='<i></i><i></i><i></i><i></i><i></i><span></span><span></span><span></span><span></span><span></span><span></span>';
  main.prepend(layer);
  const reduce=window.matchMedia('(prefers-reduced-motion: reduce)');
  const footprintTones=['violet','green','cyan','blue','yellow'];
  let lastX=-100,lastY=-100,lastTime=0,step=0;
  document.addEventListener('pointermove',e=>{
    if(settings?.pawTrailEnabled===false||reduce.matches||document.hidden||(e.pointerType&&e.pointerType!=='mouse'))return;
    const now=performance.now(),dx=e.clientX-lastX,dy=e.clientY-lastY,distance=Math.hypot(dx,dy);
    if(distance<27||now-lastTime<52)return;
    const angle=Math.atan2(dy,dx)*180/Math.PI+90,side=step%2===0?-5:5,length=Math.max(distance,1);
    const paw=document.createElement('span');
    paw.className=`paw-trail paw-${footprintTones[step%footprintTones.length]}`;
    paw.setAttribute('aria-hidden','true');
    paw.style.left=`${e.clientX+(side*-dy/length)-6}px`;
    paw.style.top=`${e.clientY+(side*dx/length)-7}px`;
    paw.style.rotate=`${angle}deg`;
    document.body.appendChild(paw);
    step++;lastX=e.clientX;lastY=e.clientY;lastTime=now;
    const paws=document.querySelectorAll('.paw-trail');if(paws.length>24)paws[0].remove();
    paw.addEventListener('animationend',()=>paw.remove(),{once:true});
    setTimeout(()=>paw.remove(),1400);
  },{passive:true});
  document.addEventListener('pointerdown',e=>{
    if(e.button!==0||settings?.clickEffectEnabled===false)return;
    const burst=document.createElement('span');
    burst.className='click-hamster-burst';
    burst.setAttribute('aria-hidden','true');
    burst.style.left=`${e.clientX-24}px`;burst.style.top=`${e.clientY-24}px`;
    const image=document.createElement('img');
    image.alt='';
    image.src=settings?.clickEffectDataUrl||defaultClickEffectDataUrl;
    burst.appendChild(image);
    document.body.appendChild(burst);
    burst.addEventListener('animationend',()=>burst.remove(),{once:true});
    setTimeout(()=>burst.remove(),1100);
  },{passive:true});
}
