document.querySelectorAll('[data-chat-mode]').forEach(button=>button.onclick=async()=>{await save({chatMode:button.dataset.chatMode});$('#chatStatus').textContent=button.dataset.chatMode==='local'?'已切换到免费本地聊天，不会产生费用。':'已切换到 AI 智能聊天，请确认接口设置可用。'});
async function sendChat(){const message=$('#chatInput').value.trim();if(!message||$('#sendChat').disabled)return;$('#chatInput').value='';$('#sendChat').disabled=true;$('#chatStatus').textContent=(settings.chatMode||'local')==='local'?'鼠鼠正在认真理解你说的话……':'鼠鼠正在通过 AI 思考怎么回答……';const pending={role:'user',content:message};settings={...settings,chatHistory:[...(settings.chatHistory||[]),pending]};renderChat();try{const result=await window.petAPI.chat(message);if(result?.ok){settings={...settings,chatHistory:result.history};renderChat();$('#chatStatus').textContent=result.mode==='local'?'鼠鼠已用免费本地模式回答。':'鼠鼠已经通过 AI 回答你啦。'}else{settings={...settings,chatHistory:(settings.chatHistory||[]).slice(0,-1)};renderChat();$('#chatStatus').textContent=`没有收到回复：${result?.error||'本地聊天暂时没有响应'}`}}catch(error){settings={...settings,chatHistory:(settings.chatHistory||[]).slice(0,-1)};renderChat();$('#chatStatus').textContent=`聊天连接已恢复，请再发送一次：${error?.message||'未知错误'}`}finally{$('#sendChat').disabled=false}}
$('#sendChat').onclick=sendChat;$('#chatInput').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();sendChat()}};$('#clearChat').onclick=async()=>{settings=await window.petAPI.clearChat();renderChat();$('#chatStatus').textContent='聊天记录已清空。'};
$('#heroPet').onclick=()=>{window.petAPI.petCommand('pet');$('#heroBubble').textContent='嘿嘿，摸到我啦～';$('#heroBubble').classList.add('pop');setTimeout(()=>{$('#heroBubble').classList.remove('pop');$('#heroBubble').textContent='我在这里陪你～'},2200)};
document.querySelectorAll('.nav button').forEach(button=>button.onclick=()=>{setPanel(button.dataset.panel);if(button.dataset.panel==='diary')showDiary($('#diaryDate').value||today())});
document.querySelectorAll('[data-feature-panel]').forEach(button=>button.onclick=()=>{const panel=button.dataset.featurePanel;setPanel(panel);if(panel==='diary')showDiary($('#diaryDate').value||today())});
$('#backHome').onclick=()=>setPanel('home');
function syncHeaderExpansion(){document.querySelector('main>header')?.classList.toggle('panel-expanded',$('#mouseProfilePopover').classList.contains('open'))}
function setProfileOpen(open){const popover=$('#mouseProfilePopover');$('#homeBrand').setAttribute('aria-expanded',String(open));popover.setAttribute('aria-hidden',String(!open));popover.classList.toggle('open',open);syncHeaderExpansion()}
$('#homeBrand').onclick=e=>{e.stopPropagation();setProfileOpen(!$('#mouseProfilePopover').classList.contains('open'))};
$('#mouseProfilePopover').onclick=e=>e.stopPropagation();
$('#effectSettingsButton').onclick=()=>setPanel('settings');
$('#pawTrailEnabled').onchange=e=>save({pawTrailEnabled:e.target.checked});
$('#clickEffectEnabled').onchange=e=>save({clickEffectEnabled:e.target.checked});
$('#interfaceLanguage').onchange=e=>save({interfaceLanguage:e.target.value});
$('#settingsPetForm').onchange=async e=>{await save({petForm:e.target.value});$('#formHint').textContent=petFormMessage(e.target.value)};
$('#openUnifiedSettings').onclick=()=>setPanel('settings');
$('#chooseClickEffect').onclick=()=>$('#clickEffectFile').click();
$('#restoreClickEffect').onclick=async()=>{await save({clickEffectDataUrl:''});$('#restoreClickEffect').textContent='已恢复默认鼠鼠';setTimeout(()=>$('#restoreClickEffect').textContent='恢复默认鼠鼠',1400)};
$('#clickEffectFile').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;const source=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)});const image=new Image();image.src=source;await image.decode();const max=320,scale=Math.min(1,max/Math.max(image.naturalWidth,image.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.naturalWidth*scale));canvas.height=Math.max(1,Math.round(image.naturalHeight*scale));const context=canvas.getContext('2d',{willReadFrequently:true});context.drawImage(image,0,0,canvas.width,canvas.height);const pixels=context.getImageData(0,0,canvas.width,canvas.height),data=pixels.data;for(let i=0;i<data.length;i+=4){const min=Math.min(data[i],data[i+1],data[i+2]),maxChannel=Math.max(data[i],data[i+1],data[i+2]),neutral=maxChannel-min<24;if(neutral&&min>218)data[i+3]=Math.round(data[i+3]*Math.max(0,(252-min)/34))}context.putImageData(pixels,0,0);await save({clickEffectDataUrl:canvas.toDataURL('image/png')});$('#chooseClickEffect').textContent='已自动抠图并保存';setTimeout(()=>$('#chooseClickEffect').textContent='上传自定义点击鼠鼠',1600);e.target.value=''};
document.addEventListener('click',()=>setProfileOpen(false));
document.addEventListener('keydown',e=>{if(e.key==='Escape'){setProfileOpen(false);$('#homeBrand').focus()}});
$('#togglePetTop').onclick=()=>window.petAPI.togglePet();
$('#actionGrid').onclick=async e=>{const rename=e.target.closest('[data-save-action-name]');if(rename){const input=rename.closest('article').querySelector('.action-name-input'),name=input.value.trim();if(!name){$('#actionResult').textContent='动作名称不能为空';input.focus();return}settings=await window.petAPI.renameAction(rename.dataset.saveActionName,name);render();$('#actionResult').textContent=`名称已保存：${name.slice(0,24)}`;return}const remove=e.target.closest('[data-delete-action]');if(remove){settings=await window.petAPI.deleteAction(remove.dataset.deleteAction);render();$('#actionResult').textContent='自定义动作已删除';return}const button=e.target.closest('[data-preview-action]');if(!button)return;await save({petForm:'real'});window.petAPI.petCommand(`action:${button.dataset.previewAction}`);const item=allActions().find(x=>x.id===button.dataset.previewAction);$('#actionResult').textContent=`正在桌面预览：${item.name}`};
$('#importAction').onclick=async()=>{const name=$('#customActionName').value.trim();$('#actionResult').textContent='请选择一个已经透明的动作文件…';const result=await window.petAPI.importAction(name);if(result.cancelled){$('#actionResult').textContent='没有选择文件';return}if(result.error){$('#actionResult').textContent=`添加失败：${result.error}`;return}settings=result.settings;$('#customActionName').value='';render();$('#actionResult').textContent=`已添加动作：${result.item.name}`};
$('#diaryDate').value=today();$('#diaryDate').max=today();$('#diaryDate').onchange=e=>showDiary(e.target.value);$('#diaryArchive').onclick=e=>{const b=e.target.closest('[data-diary-date]');if(b)showDiary(b.dataset.diaryDate)};$('#openDiary').onclick=()=>{setPanel('diary');showDiary(today())};
document.querySelectorAll('[data-quick]').forEach(button=>button.onclick=async()=>{const a=button.dataset.quick;if(a==='pet'){window.petAPI.petCommand('pet');$('#quickResult').textContent='鼠鼠开心地蹭了蹭你！'}else if(a==='feed'){settings=await window.petAPI.feed('leaf');render();$('#quickResult').textContent='鼠鼠抱着菜叶认真地吃起来了。'}else if(a==='form'){const next=nextPetForm(settings.petForm||'3d');await save({petForm:next});$('#quickResult').textContent=petFormMessage(next)}else if(a==='outfit')setPanel('behavior');else if(a==='wheel'){window.petAPI.petCommand('wheel');$('#quickResult').textContent='鼠鼠已经跳上跑轮啦！'}else if(a==='show'){window.petAPI.petCommand('show');$('#quickResult').textContent='鼠鼠已经出来陪你啦！'}setTimeout(refreshHome,300)});
renderAge();renderHeroGreeting();setPanel('home');setTimeout(refreshFeedSummary,500);setInterval(()=>{refreshHome();refreshFeedSummary();renderHeroGreeting()},60000);

