const originalUiText=new WeakMap();
function translateWholeInterface(lang){
  const dict=exactUiText[lang]||{};
  const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT,{acceptNode(node){return /\S/.test(node.nodeValue)&&!node.parentElement.closest('script,style')?NodeFilter.FILTER_ACCEPT:NodeFilter.FILTER_REJECT}});
  const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);
  nodes.forEach(node=>{if(!originalUiText.has(node))originalUiText.set(node,node.nodeValue);const raw=originalUiText.get(node),trim=raw.trim(),name=lang==='en'?'Hamster':'Hámster';let translated=lang==='zh'?trim:(dict[trim]||trim.replaceAll('鼠鼠的小日记',lang==='en'?"Hamster’s diary":'Diario de Hámster').replaceAll('鼠鼠',name).replaceAll('小鼠',name));const age=trim.match(/^(\d+)岁(\d+)个月$/);if(lang!=='zh'&&age)translated=lang==='en'?`${age[1]}y ${age[2]}m`:`${age[1]} a ${age[2]} m`;if(lang!=='zh'&&node.parentElement.closest('.diary-title,.diary-stats,#diaryArchive'))translated=translated.replaceAll('今天',lang==='en'?'Today':'Hoy').replaceAll('互动',lang==='en'?'Interactions':'Interacciones').replaceAll('投喂',lang==='en'?'Feeds':'Comidas').replaceAll('跑轮',lang==='en'?'Wheel runs':'Carreras');node.nodeValue=raw.replace(trim,translated)});
  document.querySelectorAll('input[placeholder],textarea[placeholder]').forEach(node=>{if(!node.dataset.zhPlaceholder)node.dataset.zhPlaceholder=node.placeholder;const raw=node.dataset.zhPlaceholder;node.placeholder=lang==='zh'?raw:(dict[raw]||raw)});
  const brand=$('#homeBrand b');if(brand)brand.textContent=lang==='en'?'Hamster':lang==='es'?'Hámster':'鼠鼠';
}
const baseApplyLanguage=applyLanguage;
applyLanguage=function(){baseApplyLanguage();translateWholeInterface(settings?.interfaceLanguage||'zh')};
const baseSetPanel=setPanel;
setPanel=function(name){baseSetPanel(name);applyLanguage()};
$('#homeBrand').onclick=e=>{e.stopPropagation();setPanel('profile')};

/* v17: centered companion controls and independent user feedback flow */
let feedbackFiles=[];
function feedbackPayload(){return {type:document.querySelector('input[name="feedbackType"]:checked')?.value||'其他',description:$('#feedbackDescription')?.value.trim()||'',contact:$('#feedbackContact')?.value.trim()||'',files:feedbackFiles}}
function updateFeedbackState(){if(!$('#feedbackDescription'))return;const length=$('#feedbackDescription').value.length;$('#feedbackCount').textContent=length;$('#submitFeedback').disabled=!$('#feedbackDescription').value.trim();if(!$('#feedbackDescription').value.trim())$('#feedbackStatus').textContent='填写问题描述后即可提交'}
function renderFeedbackFiles(){if(!$('#feedbackFiles'))return;$('#feedbackFiles').innerHTML=feedbackFiles.map(file=>`<li>${escapeHtml(file.name)}</li>`).join('')}
function restoreFeedbackDraft(){const draft=settings?.feedbackDraft;if(!draft||!$('#feedbackDescription'))return;$('#feedbackDescription').value=draft.description||'';$('#feedbackContact').value=draft.contact||'';const type=document.querySelector(`input[name="feedbackType"][value="${CSS.escape(draft.type||'功能异常')}"]`);if(type)type.checked=true;feedbackFiles=Array.isArray(draft.files)?draft.files:[];renderFeedbackFiles();updateFeedbackState()}
$('#feedbackButton').onclick=()=>setPanel('feedback');
$('#feedbackDescription').oninput=updateFeedbackState;
$('#chooseFeedbackFiles').onclick=async()=>{feedbackFiles=await window.petAPI.chooseFeedbackFiles();renderFeedbackFiles();$('#feedbackStatus').textContent=feedbackFiles.length?'已选择附件，请在打开的 GitHub 页面中手动添加':'没有选择附件'};
$('#saveFeedbackDraft').onclick=async()=>{await save({feedbackDraft:feedbackPayload()});$('#feedbackStatus').textContent='草稿已保存在这台电脑'};
$('#viewFeedbackIssues').onclick=()=>window.petAPI.openFeedbackIssues();
$('#feedbackForm').onsubmit=async e=>{e.preventDefault();const payload=feedbackPayload();if(!payload.description)return updateFeedbackState();$('#submitFeedback').disabled=true;$('#feedbackStatus').textContent='正在打开 GitHub 反馈页面…';const result=await window.petAPI.submitFeedback(payload);$('#submitFeedback').disabled=false;$('#feedbackStatus').textContent=result?.ok?'已打开 GitHub，请检查内容并点击提交':result?.error||'暂时无法打开反馈页面'};
window.petAPI.getSettings().then(()=>restoreFeedbackDraft());
